    6930432 <= ov <= 140737488355272 -> ov mod 8 = 0 -> (2147446784 + 17592186048512 <= ov \/ ov + 56 <= 2147446784) -> L5KA.zeros_at M ((ov / 8) + 2147450880) 7 ->
    L5.writable RSEGS M ov 56 -> ((sp - 32) + 32 <= ov \/ ov + 56 <= (sp - 32)) -> L5.u64_at RSEGS M ov 1277312 -> L5KA.zeros_at M sh 1 ->
    L5.u32_at RSEGS M (op + 12) dp -> 1 <= dp <= 1024 -> (op + 384 <= ov \/ ov + 56 <= op) -> L5.u8_at RSEGS M (op + 16) 0 ->
    L5.u32_at RSEGS M (op + 20) 0 -> L5.u64_at RSEGS M (op + 360) b -> L5.u64_at RSEGS M (op + 368) (b + sz) -> 4096 <= b <= 140737488289792 ->
    64 <= sz <= 32800 -> sz mod 32 = 0 ->
